from pptx import Presentation

print("--- Debugging Processed File ---")
prs = Presentation("/root/Awesome-Agent-Papers_processed.pptx")
last_slide = prs.slides[-1]
print(f"Last Slide Title: {last_slide.shapes.title.text}")

for shape in last_slide.shapes:
    if shape.has_text_frame and shape != last_slide.shapes.title:
        print(f"Shape {shape.name} TextFrame:")
        for i, p in enumerate(shape.text_frame.paragraphs):
            print(f"  Para {i}: '{p.text}'")

print("\n--- Debugging Title Extraction Logic ---")
# Re-check extraction logic on the original file (or processed if they are still there)
# We can check processed file slides 0-2
for i, slide in enumerate(prs.slides[:3]):
    print(f"Slide {i}:")
    for shape in slide.shapes:
        if not shape.has_text_frame:
            continue
        if shape.is_placeholder:
            continue
        if not shape.text.strip():
            continue
        print(f"  Found Candidate: '{shape.text}'")
        print(f"  Font: {shape.text_frame.paragraphs[0].font.name}, Size: {shape.text_frame.paragraphs[0].font.size}, Color: {shape.text_frame.paragraphs[0].font.color.rgb if shape.text_frame.paragraphs[0].font.color else 'None'}")
EOF
